import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String text = next(), prefix = next(), suffix = next();
        int bestScore = -1;
        String best = "";
        for (int l = 0; l < text.length(); l++)
            for (int r = l + 1; r <= text.length(); r++) {
                String part = text.substring(l, r);
                int a = 0, b = 0;
                // Longest k: part starts with the last k characters of prefix.
                for (int k = 1; k <= Math.min(part.length(), prefix.length()); k++)
                    if (part.startsWith(prefix.substring(prefix.length() - k))) a = k;
                // Longest k: part ends with the first k characters of suffix.
                for (int k = 1; k <= Math.min(part.length(), suffix.length()); k++)
                    if (part.endsWith(suffix.substring(0, k))) b = k;
                int score = a + b;
                if (score > bestScore || (score == bestScore && part.compareTo(best) < 0)) {
                    bestScore = score;
                    best = part;
                }
            }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	text, prefix, suffix := string(token()), string(token()), string(token())
	bestScore, best := -1, ""
	for l := 0; l < len(text); l++ {
		for r := l + 1; r <= len(text); r++ {
			part := text[l:r]
			a, b := 0, 0
			// Longest k: part starts with the last k characters of prefix.
			for k := 1; k <= min(len(part), len(prefix)); k++ {
				if strings.HasPrefix(part, prefix[len(prefix)-k:]) {
					a = k
				}
			}
			// Longest k: part ends with the first k characters of suffix.
			for k := 1; k <= min(len(part), len(suffix)); k++ {
				if strings.HasSuffix(part, suffix[:k]) {
					b = k
				}
			}
			score := a + b
			if score > bestScore || (score == bestScore && part < best) {
				bestScore, best = score, part
			}
		}
	}
	fmt.Println(best)
}
